pub(super) fn summarize<D: Decision>(
    decisions: &[D],
    retained_entries: usize,
    scope: Scope,
    contract: Contract,
) -> Summary {
    let hidden_findings = decisions
        .iter()
        .filter(|decision| matches!(decision.state(), "hidden_exact" | "hidden_growth"))
        .count();
    let complete = scope.complete
        && decisions
            .iter()
            .all(|decision| decision.state() != "unavailable");
    Summary {
        schema: contract.schema,
        execution: if scope.requested {
            Execution::Completed
        } else {
            Execution::NotRequested
        },
        coverage: if scope.requested && complete {
            Coverage::Complete
        } else {
            Coverage::Incomplete
        },
        findings: decisions.len(),
        hidden_findings,
        visible_findings: decisions.len() - hidden_findings,
        retained_entries,
        reasons: if scope.requested && !scope.complete {
            vec![contract.incomplete_scope]
        } else {
            Vec::new()
        },
    }
}

pub fn align_variant(ctx: &Ctx<'_>, v: Variant) -> (Alignment, Vec<Stage>) {
    let depth = ctx.wa.rounds.len().min(ctx.levels_used());
    let levels: Vec<Ctx<'_>> = (0..depth.max(1)).map(|k| ctx.at_level(k)).collect();
    let empty = Matching::new(ctx.ca.len(), ctx.cb.len());
    let (_, stages) =
        steps(ctx, &levels, v)
            .iter()
            .fold((empty, Vec::new()), |(m, mut stages), (name, run)| {
                let next = run(m);
                stages.push(Stage {
                    name,
                    pairs: next.pairs(),
                });
                (next, stages)
            });
    let pairs = stages.last().map_or_else(Vec::new, |s| s.pairs.clone());
    let larger = ctx.ca.len().max(ctx.cb.len()).max(1);
    let alignment = Alignment {
        coverage_milli: (pairs.len() * 1000 / larger) as u32,
        holes: holes_of(ctx, &pairs),
        pairs,
    };

    (alignment, stages)
}
